## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

module tb;
  localparam int CLK_PERIOD = 10;
  localparam logic [15:0] PRESCALE = 16'd1;

  logic clk = 0;
  logic rst = 0;
  logic [7:0] m_axis_tdata;
  logic m_axis_tvalid;
  logic m_axis_tready = 0;
  logic rxd = 1;
  logic [15:0] prescale = PRESCALE;
  logic rx_busy;
  logic rx_overrun_error;
  logic rx_frame_error;
  logic [7:0] s_axis_tdata = 0;
  logic s_axis_tvalid = 0;
  logic s_axis_tready;
  logic txd;
  logic tx_busy;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart #(.DATA_WIDTH(8)) dut (
    .clk(clk),
    .rst(rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .txd(txd),
    .tx_busy(tx_busy),
    .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1;
    wait_clks(4);
    rst = 0;
    wait_clks(2);
  endtask

  initial begin
    m_axis_tready = 0;
    rxd = 1;
    s_axis_tdata = 0;
    s_axis_tvalid = 0;
    prescale = PRESCALE;

    do_reset();

    // ---- Frame 1: data 0x3C, good stop bit, sink stalled (tready=0) ----
    // After this frame m_axis_tvalid=1, m_axis_tdata=0x3C, held unread.
    rxd = 0;
    wait_clks(int'(prescale) * 8);
    for (int i = 0; i < 8; i++) begin
      rxd = (8'h3C >> i) & 1'b1;
      wait_clks(int'(prescale) * 8);
    end
    rxd = 1;
    wait_clks(int'(prescale) * 8);

    // Wait until the word is presented on the AXI output
    do @(negedge clk); while (!m_axis_tvalid);
    if (m_axis_tdata !== 8'h3C) begin
      $display("FAIL: unexpected tdata 0x%02h", m_axis_tdata);
      $finish;
    end

    // ---- Frame 2: all-zero data, bad stop bit (0) -> frame_error ----
    // Keep m_axis_tready low through the start + 8 data bits and 7 of the
    // 8 stop-bit clocks, then release it on the final stop-bit clock so
    // that the 0x3C handshake (tvalid&tready) lands on the same posedge
    // as the frame-error strobe.  On the next posedge tvalid has dropped
    // while tdata still holds 0x3C, satisfying R29.
    rxd = 0;
    wait_clks(int'(prescale) * 8);
    for (int i = 0; i < 8; i++) begin
      rxd = 0;
      wait_clks(int'(prescale) * 8);
    end
    rxd = 0;  // bad stop bit
    wait_clks(int'(prescale) * 8 - 1);
    m_axis_tready = 1;
    wait_clks(4);

    $finish;
  end

  initial begin
    #10ms;
    $finish;
  end

endmodule
```

